<?php
/* Plugin Name: Medexos Catalogue Requests
Description: Catalogue landing pages and request forms for Medexos Surgical.
Version: 0.1.0
*/
if (!defined('ABSPATH')) exit;
function medexos_catalogues(){return array(
'orthopedic-spinal-instruments'=>array('title'=>'Orthopedic Spinal Instruments','pdf'=>'orthopedic-spinal.pdf'),
'ophthalmic-instruments'=>array('title'=>'Ophthalmic Instruments','pdf'=>'ophthalmic.pdf'),
'laryngoscopes'=>array('title'=>'Laryngoscopes','pdf'=>'laryngoscope.pdf'),
'liposuction-cannulas-accessories'=>array('title'=>'Liposuction Cannulas & Accessories','pdf'=>'liposuction.pdf'),
'plastic-surgery-instruments'=>array('title'=>'Plastic Surgery Instruments','pdf'=>'plastic-surgery.pdf'),
'retractor-systems'=>array('title'=>'Retractor Systems','pdf'=>'retractors.pdf'),
'veterinary-orthopedic-implants'=>array('title'=>'Veterinary Orthopedic Implants','pdf'=>'veterinary.pdf'));
}
function medexos_asset_url($path){return plugins_url('assets/'.$path,__FILE__);}
add_action('admin_menu',function(){add_management_page('Medexos catalogue setup','Medexos catalogue setup','manage_options','medexos-setup','medexos_admin');});
function medexos_admin(){if(!current_user_can('manage_options'))return; if(isset($_POST['medexos_setup'])){check_admin_referer('medexos_setup');foreach(medexos_catalogues() as $key=>$v){if(!get_page_by_path($key)){wp_insert_post(array('post_title'=>$v['title'],'post_name'=>$key,'post_status'=>'draft','post_type'=>'page','post_content'=>'[medexos_catalogue id="'.$key.'"]'));}}echo '<div class="notice notice-success"><p>Missing catalogue pages were created as drafts. Review and publish them in Pages.</p></div>'; } if(isset($_POST['medexos_settings'])){check_admin_referer('medexos_settings');$email=sanitize_email(wp_unslash($_POST['recipient'] ?? ''));if(is_email($email))update_option('medexos_recipient',$email); foreach(medexos_catalogues() as $key=>$v){$url=esc_url_raw(wp_unslash($_POST['url'][$key] ?? ''));update_option('medexos_pdf_'.$key,$url);}echo '<div class="notice notice-success"><p>Settings saved.</p></div>'; } ?><div class="wrap"><h1>Medexos catalogue setup</h1><p>Create draft catalogue pages without modifying existing pages. Pages with the same slug are left untouched.</p><form method="post"><?php wp_nonce_field('medexos_setup'); ?><button class="button button-primary" name="medexos_setup" value="1">Create missing catalogue page drafts</button></form><h2>Catalogue delivery settings</h2><p>PDF links are public and shareable. Enter a PDF URL, or leave it blank only if you supplied the matching PDF in the plugin assets/pdf directory. Configure SMTP and test delivery before launch.</p><form method="post"><?php wp_nonce_field('medexos_settings'); ?><p><label>Enquiry recipient <input type="email" name="recipient" required value="<?php echo esc_attr(get_option('medexos_recipient',get_option('admin_email'))); ?>"></label></p><?php foreach(medexos_catalogues() as $key=>$v): ?><p><label><?php echo esc_html($v['title']); ?> PDF URL<br><input class="regular-text" type="url" name="url[<?php echo esc_attr($key); ?>]" value="<?php echo esc_attr(get_option('medexos_pdf_'.$key,'')); ?>"></label></p><?php endforeach; ?><button class="button button-primary" name="medexos_settings" value="1">Save settings</button></form></div><?php }
add_shortcode('medexos_catalogue',function($atts){$a=shortcode_atts(array('id'=>''),$atts);$all=medexos_catalogues();$id=sanitize_key($a['id']);if(!isset($all[$id]))return ''; $item=$all[$id];$state=isset($_GET['catalogue_status'])?sanitize_key(wp_unslash($_GET['catalogue_status'])):'';ob_start();?><div class="catalogue-layout"><div><img src="<?php echo esc_url(medexos_asset_url('covers/'.$id.'.jpg')); ?>" alt="<?php echo esc_attr($item['title'].' catalogue cover'); ?>"><p>Explore our <?php echo esc_html(strtolower($item['title'])); ?> catalogue. Complete the form to receive a link by email, or contact our team to discuss your requirements.</p></div><div><h2>Request the catalogue</h2><?php if($state==='sent'): ?><p class="notice" role="status">Thank you. Your request has been submitted and the catalogue email has been sent. Please check your inbox and spam folder.</p><?php elseif($state==='error'): ?><p class="notice" role="alert">We could not complete your request. Please check your details or contact us directly.</p><?php endif; ?><form class="form" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="medexos_request"><input type="hidden" name="catalogue" value="<?php echo esc_attr($id); ?>"><input type="hidden" name="return_to" value="<?php echo esc_url(get_permalink()); ?>"><?php wp_nonce_field('medexos_request_'.$id,'medexos_nonce'); ?><div class="trap" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><label for="m-name">Name *</label><input id="m-name" name="name" maxlength="100" required><label for="m-email">Email *</label><input id="m-email" type="email" name="email" maxlength="254" required><label for="m-company">Company</label><input id="m-company" name="company" maxlength="100"><label for="m-country">Country *</label><input id="m-country" name="country" maxlength="100" required><label for="m-message">Message</label><textarea id="m-message" name="message" maxlength="2000"></textarea><p><label class="check"><input type="checkbox" name="privacy" value="1" required> I agree to the processing of my details for this catalogue request. <?php if(get_privacy_policy_url()): ?><a href="<?php echo esc_url(get_privacy_policy_url()); ?>">Privacy policy</a><?php endif; ?></label></p><button type="submit">Send me the catalogue</button></form></div></div><?php return ob_get_clean();});
function medexos_handle_request(){ $all=medexos_catalogues();$id=sanitize_key(wp_unslash($_POST['catalogue']??''));$fallback=home_url('/');$return=wp_validate_redirect(esc_url_raw(wp_unslash($_POST['return_to']??'')),$fallback);$fail=function()use($return){wp_safe_redirect(add_query_arg('catalogue_status','error',$return));exit;};if(!isset($all[$id])||!isset($_POST['medexos_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['medexos_nonce'])),'medexos_request_'.$id)||!empty($_POST['website'])||empty($_POST['privacy']))$fail();$name=sanitize_text_field(wp_unslash($_POST['name']??''));$email=sanitize_email(wp_unslash($_POST['email']??''));$company=sanitize_text_field(wp_unslash($_POST['company']??''));$country=sanitize_text_field(wp_unslash($_POST['country']??''));$message=sanitize_textarea_field(wp_unslash($_POST['message']??''));if(!$name||!is_email($email)||!$country||strlen($message)>2000)$fail();$ip=isset($_SERVER['REMOTE_ADDR'])?sanitize_text_field(wp_unslash($_SERVER['REMOTE_ADDR'])):'unknown';$limit='medexos_'.hash_hmac('sha256',$ip,wp_salt('nonce'));if(get_transient($limit))$fail();set_transient($limit,1,60);$url=get_option('medexos_pdf_'.$id,'');if(!$url){ $pdf = 'pdf/'.$all[$id]['pdf']; if (!is_readable(__DIR__.'/assets/'.$pdf)) $fail(); $url=medexos_asset_url($pdf); }$recipient=get_option('medexos_recipient',get_option('admin_email'));if(!is_email($recipient))$fail();$subject='Catalogue request: '.$all[$id]['title'];$body="Name: $name\nEmail: $email\nCompany: $company\nCountry: $country\nCatalogue: ".$all[$id]['title']."\n\nMessage:\n$message";$ok1=wp_mail($recipient,$subject,$body,array('Reply-To: '.$email));$ok2=wp_mail($email,'Your Medexos catalogue: '.$all[$id]['title'],"Hello $name,\n\nThank you for your interest in Medexos Surgical. Download the requested catalogue here:\n$url\n\nFor further information, please contact our team.\n\nMedexos Surgical Enterprises");if(!$ok1||!$ok2)$fail();wp_safe_redirect(add_query_arg('catalogue_status','sent',$return));exit;}
add_action('admin_post_nopriv_medexos_request','medexos_handle_request');add_action('admin_post_medexos_request','medexos_handle_request');
